package frflow.lint

import frflow.model.*

enum Severity:
  case Error, Warning

final case class LintIssue(severity: Severity, nodeId: Option[String], code: String, message: String):
  def render: String =
    val where = nodeId.fold("")(id => s"[$id] ")
    s"${severity.toString.toLowerCase} $code: $where$message"

/** Structural and coherence rules. Errors block rendering and checking;
  * warnings are reported.
  */
object Lints:

  final case class Limits(
      maxStatementChars: Int = 400,
      maxStatementSentences: Int = 3,
      maxChildren: Int = 7
  )

  /** Names generated by the renderer inside a node namespace. */
  val ReservedNodeNames: Set[String] =
    Set("State", "Init", "machine", "abs", "glue", "Obl", "Proofs", "Hyp", "invariant", "refinement")

  private val LeanKeywords: Set[String] = Set(
    "abbrev", "axiom", "by", "class", "def", "deriving", "do", "else", "end", "example", "export", "fun",
    "have", "if", "import", "in", "inductive", "instance", "let", "match", "namespace", "open", "opaque",
    "private", "protected", "section", "show", "structure", "then", "theorem", "universe", "variable",
    "where", "with", "at", "from", "mut", "return", "for", "unless", "macro", "syntax", "set_option",
    "noncomputable", "partial", "unsafe", "sorry", "admit", "Type", "Prop", "Sort"
  )

  private val Ident = """[A-Za-z_][A-Za-z0-9_]*""".r

  def isValidIdent(s: String): Boolean = Ident.matches(s) && !LeanKeywords(s)

  def run(theory: TheoryModel, limits: Limits = Limits()): Seq[LintIssue] =
    val issues = Seq.newBuilder[LintIssue]
    def err(node: Option[String], code: String, msg: String) = issues += LintIssue(Severity.Error, node, code, msg)
    def warn(node: Option[String], code: String, msg: String) = issues += LintIssue(Severity.Warning, node, code, msg)

    // Theory-level
    if !isValidIdent(theory.name) then err(None, "FR001", s"theory name '${theory.name}' is not a valid Lean identifier")
    if theory.nodes.isEmpty then err(None, "FR002", "theory has no nodes")
    if theory.roots.size > 1 then
      err(None, "FR003", s"theory must have exactly one root, found ${theory.roots.map(_.id).mkString(", ")}")

    duplicates(theory.nodes.map(_.id)).foreach(d => err(None, "FR004", s"duplicate node id '$d'"))
    duplicates(theory.vocabulary.map(_.name)).foreach(d => err(None, "FR005", s"duplicate vocabulary entry '$d'"))
    duplicates(theory.assumptions.map(_.id)).foreach(d => err(None, "FR006", s"duplicate assumption id '$d'"))

    theory.vocabulary.foreach { v =>
      if !isValidIdent(v.name) then err(None, "FR007", s"vocabulary name '${v.name}' is not a valid Lean identifier")
      if v.doc.trim.isEmpty then warn(None, "FR008", s"vocabulary entry '${v.name}' has no documentation")
    }

    val nodeIds = theory.nodes.map(_.id).toSet
    val usedAssumptions = theory.nodes.flatMap(_.spec.events.flatMap(_.assumes.map(_.assumptionId))).toSet
    theory.assumptions.foreach { a =>
      if a.statement.trim.isEmpty then err(None, "FR009", s"assumption ${a.id} has no statement")
      if a.justification.trim.isEmpty then
        err(None, "FR010", s"assumption ${a.id} has no justification (why the environment satisfies it)")
      if !usedAssumptions(a.id) then warn(None, "FR011", s"assumption ${a.id} is declared but not used by any event")
    }

    theory.nodes.foreach { n =>
      val id = Some(n.id)
      if !isValidIdent(n.id) then err(id, "FR020", s"node id '${n.id}' is not a valid Lean identifier")

      // Statement discipline: short, explicit, justified.
      val stmt = n.statement.trim
      if stmt.isEmpty then err(id, "FR021", "statement is empty")
      if stmt.length > limits.maxStatementChars then
        err(id, "FR022", s"statement has ${stmt.length} characters (limit ${limits.maxStatementChars}); split the node")
      val sentences = stmt.split("""(?<=[.!?])\s+""").count(_.trim.nonEmpty)
      if sentences > limits.maxStatementSentences then
        err(id, "FR023", s"statement has $sentences sentences (limit ${limits.maxStatementSentences})")
      if n.rationale.trim.isEmpty then warn(id, "FR024", "rationale is empty: record why this decomposition was chosen")

      val kids = theory.children(n.id)
      if kids.size > limits.maxChildren then
        err(id, "FR025", s"node has ${kids.size} children (limit ${limits.maxChildren}); introduce an intermediate node")

      // Parent and link
      n.parent.foreach { p =>
        if !nodeIds(p) then err(id, "FR026", s"parent '$p' does not exist")
        if theory.ancestors(n).exists(_.id == n.id) then err(id, "FR027", "node is its own ancestor")
      }
      if n.parent.isDefined && n.link.isEmpty then err(id, "FR028", "refining node has no link to its parent")
      if n.parent.isEmpty && n.link.isDefined then err(id, "FR029", "root node must not have a link")

      // Names inside the node namespace
      val localNames =
        n.spec.state.map(_.name) // fields live in State, but keep them identifier-safe
      localNames.filterNot(isValidIdent).foreach(f => err(id, "FR030", s"state field '$f' is not a valid identifier"))
      duplicates(n.spec.state.map(_.name)).foreach(f => err(id, "FR031", s"duplicate state field '$f'"))
      if n.spec.state.isEmpty then warn(id, "FR032", "state has no fields")

      val topNames = n.spec.events.map(_.name) ++ n.spec.invariants.map(_.name)
      duplicates(topNames).foreach(x => err(id, "FR033", s"name '$x' is declared more than once"))
      topNames.foreach { x =>
        if !isValidIdent(x) then err(id, "FR034", s"'$x' is not a valid Lean identifier")
        if ReservedNodeNames(x) then err(id, "FR035", s"'$x' is reserved by the renderer")
      }
      theory.vocabulary.map(_.name).filter(v => topNames.contains(v)).foreach { v =>
        err(id, "FR036", s"'$v' shadows a vocabulary entry")
      }

      if n.spec.events.isEmpty then warn(id, "FR037", "node has no events")

      val parentNode = theory.parentOf(n)
      n.spec.events.foreach { e =>
        e.parameters.map(_.name).filterNot(isValidIdent).foreach { pn =>
          err(id, "FR040", s"event ${e.name}: parameter '$pn' is not a valid identifier")
        }
        duplicates(e.parameters.map(_.name)).foreach(pn => err(id, "FR041", s"event ${e.name}: duplicate parameter '$pn'"))
        e.assumes.foreach { a =>
          if theory.assumption(a.assumptionId).isEmpty then
            err(id, "FR042", s"event ${e.name}: assume clause cites unknown assumption '${a.assumptionId}'")
        }
        (parentNode, e.target) match
          case (None, EventTarget.Unspecified) => ()
          case (None, _) =>
            err(id, "FR043", s"event ${e.name}: root events must not declare a refinement target")
          case (Some(_), EventTarget.Unspecified) =>
            err(id, "FR044", s"event ${e.name}: every event of a refining node must refine a parent event or skip")
          case (Some(p), EventTarget.Refines(ae, w)) =>
            if p.event(ae).isEmpty then
              err(id, "FR045", s"event ${e.name}: refines unknown parent event ${p.id}.$ae")
            if w.text.trim.isEmpty then err(id, "FR046", s"event ${e.name}: witness is empty")
          case (Some(_), EventTarget.Skip) => ()
      }

      // Abstract events that no concrete event refines can never happen in the refined system.
      parentNode.foreach { p =>
        val refined = n.spec.events.collect { case EventDef(_, _, _, _, _, EventTarget.Refines(ae, _), _) => ae }.toSet
        p.spec.events.map(_.name).filterNot(refined).foreach { ae =>
          warn(id, "FR047", s"parent event ${p.id}.$ae is not refined by any event (it becomes disabled)")
        }
      }
    }
    issues.result()

  def errors(issues: Seq[LintIssue]): Seq[LintIssue] = issues.filter(_.severity == Severity.Error)

  private def duplicates(xs: Seq[String]): Seq[String] =
    xs.groupBy(identity).collect { case (k, v) if v.size > 1 => k }.toSeq.sorted
